source='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    row_dividers = [r for r, row in enumerate(grid) if row[0] != 0 and all(v == row[0] for v in row)]
    col_dividers = [c for c in range(w) if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h))]

    def spans(size, dividers):
        result, start = [], 0
        for d in dividers:
            if start < d:
                result.append((start, d))
            start = d + 1
        if start < size:
            result.append((start, size))
        return result

    rs, cs = spans(h, row_dividers), spans(w, col_dividers)
    if len(cs) < 2:
        return out
    cells = [[ [row[c0:c1] for row in grid[r0:r1]]
               for c0, c1 in cs] for r0, r1 in rs]

    def occupied(cell):
        return any(v != 0 for row in cell for v in row)

    def mirror(cell):
        return [row[::-1] for row in cell]

    anchors = []
    for row in cells:
        for c in range(len(cs) - 1):
            left, right = row[c], row[c + 1]
            if occupied(left) and occupied(right) and left == mirror(right):
                anchors.append(c)
    if not anchors:
        return out
    parity = anchors[0] % 2

    for ri, row in enumerate(cells):
        for c in range(parity, len(cs) - 1, 2):
            left, right = row[c], row[c + 1]
            left_on, right_on = occupied(left), occupied(right)
            if left_on and not right_on:
                replacement = mirror(left)
                r0, r1 = rs[ri]
                c0, c1 = cs[c + 1]
                for dr, values in enumerate(replacement):
                    out[r0 + dr][c0:c1] = values
            elif right_on and not left_on:
                replacement = mirror(right)
                r0, r1 = rs[ri]
                c0, c1 = cs[c]
                for dr, values in enumerate(replacement):
                    out[r0 + dr][c0:c1] = values
    return out
'''
